import {migrationShow,migrationSales} from './migration-view.js';
import {migrationFromLegacy} from './migration-model.js';
import {cloudStory} from './cloud-story.js';
import {environments,lessons,scenarioGuidance} from './cloud-model.js';
export function cloudLearn(s){const l=lessons[s.lesson];return `<div class="cloud-learning"><nav class="lesson-list" aria-label="Cloud learning modules">${lessons.map((l,i)=>`<button data-cloud="lesson" data-value="${i}" aria-pressed="${s.lesson===i}" class="${s.lesson===i?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${l[0]}</button>`).join('')}</nav><article class="lesson-body" aria-live="polite"><div class="eyebrow">LEARN / CLOUD IN BUSINESS LANGUAGE</div><h2>${l[0]}</h2><p class="lesson-main">${l[1]}</p><h3>A familiar example</h3><p>${l[2]}</p><h3>What to ask next</h3><p>${l[3]}</p><button class="primary" data-mode="show">Try it in the simulator ↗</button></article></div>`;}
export function cloudShow(s,view,rehearsal){if(!s.environment)return `<section class="cloud-start"><div class="eyebrow">START WITH YOUR BUSINESS</div><h2>Where does your work run today?</h2><p>Choose a starting environment. Then change the conditions.</p><div class="environment-choices">${environments.map((e,i)=>`<button data-cloud="environment" data-value="${e}"><span>${['▥','⋈','☁'][i]}</span><strong>${e}</strong><small>${['Infrastructure at your premises','A connected mix of local and cloud','Workloads at a cloud provider'][i]}</small><b>Build environment ↗</b></button>`).join('')}</div><p class="sim-disclaimer">A conceptual simulation. No live systems or customer data are connected.</p></section>`;
return s.migration?migrationShow(rehearsal||migrationFromLegacy(s),s.environment):cloudStory(s,view);}
export function cloudSales(s,rehearsal){if(s.migration)return migrationSales(rehearsal||migrationFromLegacy(s));const guide=scenarioGuidance[s.scenario]||{ask:'Which workload matters most, and what happens if it becomes unavailable?',listen:'Business priorities · Current environment · Workload ownership',probe:'Who is affected, how often, and what outcome would matter?',connect:'Connect the stated problem to an assessment before discussing technology.',next:'Agree discovery with the workload owner and presales.'};return `<h3>SAY</h3><p>“Let’s change one condition and look at the business consequence.”</p><h3>ASK</h3><p>${guide.ask}</p><h3>LISTEN FOR</h3><p>${guide.listen}</p><h3>PROBE</h3><p>${guide.probe}</p><h3>CONNECT</h3><p>${guide.connect}</p><h3>OBJECTION</h3><p>“Will cloud automatically solve this?” → The response depends on architecture, policies, dependencies and operating needs.</p><h3>NEXT MOVE</h3><p>${guide.next}</p>`;}
